            "它把模糊的语言精确化，把隐藏的信息呈现出来。\n\n"
            "这两个模式的关系像呼吸的一吸一吐：米尔顿模式是扩展空间、建立连接；"
            "元模型是聚焦信息、澄清本质。掌握这两套语言模式，你就在人类的沟通频谱中拥有了全频道调谐的能力。"
