            "而是「有些时候人们会发现，放松很容易发生。」不说主语，让听众自己代入。\n\n"
            "2. 不明确动词：使用含义广泛的动词，让听者自己填充细节。"
            "「你可以开始注意到某些变化的发生了。」——「注意到」「发生」是什么？不明确，"
            "但每个听者会在自己的内心里生成属于自己的具体版本。\n\n"
            "3. 名词化：将动词过程转化为名词，从而让动态的过程感觉更实在和固化。"
