            "理解这些维度的差异，是精确提取和精准优化策略的关键。\n\n"
            "完整策略的六大架构要素：\n\n"
            "1. 触发器：什么情境启动了这条策略？是外部的线索（比如闹钟响、老板走进来），"
            "还是内部的线索（一个突然的焦虑感、一个浮现的画面）？\n\n"
            "2. 表象系统序列：这是策略的核心——各个表象系统步骤的具体顺序。V→Ad→K→V→Exit。"
            "序列是策略的骨架，不同的顺序会产生完全不同的结果。\n\n"
            "3. 每个步骤的次感元特征：不只是『视觉步骤』，而是『一个小的、明亮的、"
            "位于右上方、快速闪烁的画面』。次感元的精确度直接影响策略的执行效果。\n\n"
            "4. 内外部检查点：策略中的每个步骤是在内部完成的（内部检视），"
            "还是需要外部信息输入的（外部检视）？比如，决策策略中的『看看市场数据』"
            "是一个外部检查点，『在内心对比过往经验』是一个内部检查点。\n\n"
            "5. 退出条件：什么信号告诉你策略完成了？对一些人来说是一个确定的身体感觉，"
