            "策略提取的三个信息来源：\n\n"
            "第一个来源：眼动线索。当对方在回忆或构建内心过程时，他的眼球运动会暗示他正在使用哪个表象系统。"
            "视觉回忆（Vr）—向左上方看；视觉构建（Vc）—向右上方看；"
