            "第二个来源：感官谓语。留意对方在语言中频繁使用的感官词汇。"
            "『我看到这个问题有三个方面……』（视觉）『我能感受到这个方案的难度……』（触觉）"
            "『让我在心里分析一下……』（内部对话）。这些词汇在自然谈话中的出现频率和先后顺序，"
