            "你在某个领域根本没有任何有效的策略。比如，你面对冲突时没有「处理冲突策略」，"
            "只有「回避」和「爆发」两种反应。在这种情况下，你需要从头设计一个新的策略。\n\n"
            "有效策略的共同特征：\n\n"
            "1. 使用所有主要表象系统。有效的策略通常不会只用单一通道。"
            "一个强大的公众表达策略应该包含：视觉（在内心预演场景），听觉（内心听到自己的声音），"
