            "2. 有一个清晰的外部检查点。策略如果不与外部现实互动，就会变成空想。"
            "在策略中需要内置一个步骤：『我现在需要看看实际情况如何』或『我需要得到对方的反馈』。\n\n"
            "3. 有一个退出标准。没有退出标准的策略会让人陷入无限循环——"
            "永远觉得还可以优化，永远不敢做出最终决定。\n\n"
            "4. 在序列中提供一个「继续信息」，不只是「停止信息」。如果有人告诉你一个策略失败了，"
            "说明其中一定有「停止你正在做的这个尝试」的信号，但没有提供「替代做法是什么」的信号。\n\n"
