            "「很好，接下来呢？你的注意力去了哪里？」继续追踪后续步骤。\n"
            "「怎么知道该做下一步了？有什么信号吗？」这是找出检查点。\n"
            "「怎么知道你做对了？」这是找出退出标准和反馈环。\n\n"
