            "- 平静/中心化（有助思考清晰）\n"
            "- 自信/力量（有助采取行动）\n"
            "- 正向情绪（如感恩或喜悦——有助维持积极视角）\n"
            "- 清晰度（有助专注当下的情境）\n"
            "- 勇气/弹性（有助面对不确定性）\n\n"
            "第二步：分别激活和锚定每个状态。用你已经掌握的心锚技术，分别访问和锚定每个状态。"
            "每个状态当它达到高峰时，用同一个物理触发信号（如同时按压左手的拇指和食指）。"
            "每个状态独立锚定到同一个触发信号上。\n\n"
            "第三步：堆叠整合。依次触发每个状态，叠加到同一个锚上。"
            "在触摸触发点时，先呼出第一个资源状态（平静），当它在峰值时继续按压，"
            "加入第二个状态（自信），感受它叠加在第一个状态之上的感觉……依次叠加所有状态。\n\n"
            "第四步：测试你的堆叠锚。打破状态，然后触发锚，注意观察："
            "所有你锚定的状态是否都出现了？有没有某个不在？身体整体感觉如何？\n\n"
            "一个经典的堆叠锚在职场场景中的应用：在进入重要的面试或演讲之前，"
