# =============================================================================
# INTERMEDIATE SEED FUNCTION
# =============================================================================

async def seed_intermediate_courses(conn):
    """Seed 6 intermediate courses and their 60 lessons."""
    # --- courses ---
    for course in COURSES_INTERMEDIATE:
        await conn.execute(
            text("""
                INSERT OR IGNORE INTO nlp_courses
                (id, title, description, level, source, lesson_count, duration_minutes, tags, cover_emoji, is_premium, sort_order, created_at)
                VALUES (:id, :title, :description, :level, :source, :lesson_count, :duration_minutes, :tags, :cover_emoji, :is_premium, :sort_order, CURRENT_TIMESTAMP)
            """),
            course,
        )

    # --- lessons ---
    lesson_count = 0
    for course_id, lessons in LESSONS_INTERMEDIATE.items():
        for lesson in lessons:
            await conn.execute(
                text("""
                    INSERT OR IGNORE INTO nlp_lessons
                    (id, course_id, title, type, content, concepts, source_refs, duration, order_num, created_at)
                    VALUES (:id, :course_id, :title, :type, :content, :concepts, :source_refs, :duration, :order_num, CURRENT_TIMESTAMP)
                """),
                lesson,
            )
            lesson_count += 1

    print(f"  ✅ Intermediate courses seeded (6 courses, {lesson_count} lessons)")


