            "第一步：建立关系和安全感。在任何干预之前，通过匹配感官语言、建立rapport、"
            "使用米尔顿模式的语言创造足够的心理安全感。如果这一步缺失，后续所有技术都可能无效，"
            "因为对方的意识处于防御状态。\n\n"
            "第二步：从感官/次感元层面入手。生理层面的干预往往是最直接、最易见效的——"
            "因为次感元操作不需要太大的认知努力就能产生体验上的改变。"
            "比如，先通过状态断裂暂停负面循环，再用次感元对比分析降低困扰体验的强度。"
            "这个早期的快速胜利能建立对后续工作的信心。\n\n"
            "第三步：从认知/信念层面深入。当对方通过次感元体验到了改变的可能性后，"
            "他的信念系统已经开始松动。这时用换框和信念转化技术来改变认知框架，"
            "效果会事半功倍。\n\n"
            "第四步：从策略/行为层面巩固。新的认知需要新的行为来巩固。"
