            "应对策略：降低新信念的强度——不必从「我不够格」直接跳到「我很优秀」，"
            "中间可以有一个「我正在成长为一个更有能力的人」的渐进信念。"
            "然后把这个新信念与一个具体的、真实的成功经历连接，让它有感觉上的依据。\n\n"
