            "他失去了一些重要的关系资源。\n\n"
            "改变生态检查的三层框架：\n\n"
            "第一层：内在生态——这个新改变与我的其他重要信念、价值观和内在部分是否兼容？"
            "一个强大的自我检查做法：闭上眼睛，想象自己带着这个改变生活一个月。"
