            "有时候，环境需要一同改变，否则个人改变会被环境反馈拉回到旧状态。\n\n"
            "总结：整合式改变的最高标准不是「问题消失」，而是「在解决问题的同时，"
            "整体生命质量得到提升」。这也是为什么生态检查应内建在每一个重大改变的终点——"
