            "教练自我管理的三大核心课题：\n\n"
            "课题一：情绪耗竭的预防。倾听他人的深层痛苦会自然消耗你的情绪资源。"
            "教练需要有三道自我保护：其一，每次教练对话前设置个人力量场"
            "（在进阶状态管理中学到的技术）——建立一个允许深度连接但过滤情感污染的"
            "心理空间。其二，每次教练对话后做一个简单的自我净化——"
            "也许是出去走几分钟、用冷水洗手、或做一个精神状态断裂。"
            "其三，控制每日最高教练对话次数——对于新手教练，建议一天不超过两次深度对话。\n\n"
            "课题二：救世主冲动的觉察。很多教练（特别是新手）有一种无意识的需求——"
            "通过「拯救」别人来确认自己的价值。这危险在于：你不会尊重对方的节奏——"
            "你的干预不是因为对方准备好了，而是因为你想看到好结果来满足自己。"
            "标志信号：「如果他不改变我就失败了」「我在他的困境中迷失了自己」。"
            "应对：持续进行自我觉察——每次对话结束后问自己：是我帮他，还是我在帮他帮自己？\n\n"
            "课题三：投射问题的管理。你自己未解决的人生议题会在对方的描述中被触发——"
